mapper.select:
SELECT p.product_id AS productId, p.seller_id AS sellerIdValue, m.nickname AS sellerNickname, p.name, p.price, s.quantity AS stockQuantity, p.status, p.category, pi.image_url AS thumbnailImageUrl FROM products p JOIN members m ON m.member_id = p.seller_id JOIN stocks s ON s.product_id = p.product_id LEFT JOIN product_images pi ON pi.product_id = p.product_id AND pi.is_thumbnail = true
AND lower(m.nickname) LIKE concat('%', lower(#{sellerNickname}), '%')
AND lower(p.name) LIKE concat('%', lower(#{productName}), '%')
AND p.price >= #{minPrice}
AND p.price <= #{maxPrice}
AND p.category = #{category}
AND p.product_id < #{lastProductId}
ORDER BY p.product_id DESC LIMIT #{limit}
